{
  "justification": "The electorate is near-centrist on left–right (4.74) but leans authoritarian (6.2) and is mildly sceptical of both redistribution (4.68) and deeper EU integration (4.73). Issue salience is dominated by cost-of-living and the general economy, with immigration prominent and classic “purity/morals” items minimal—so proportionality, authority and loyalty loom larger than equality and sanctity.",
  "foundations": [
    {"foundation": "proportionality", "basis": "SLOT 3: Living costs (19.7%), Economy-general (13.7%), Inflation (1.7%), Taxation (0.5%), Debt/deficit (0.2%).", "weight": 0.27},
    {"foundation": "authority", "basis": "SLOT 6: Authority–liberty mean 6.2; SLOT 3: Crime (2.4%), Terrorism (0.3%), Asylum (0.5%).", "weight": 0.22},
    {"foundation": "loyalty", "basis": "SLOT 3: Immigration (17.0%), Defence (1.3%), War (2.0%), Nat ident/goals-loss (0.3%); SLOT 7: EU integration 4.73 (mild Euroscepticism).", "weight": 0.18},
    {"foundation": "care", "basis": "SLOT 3: Health (7.0%), Environment (6.1%), Poverty (1.3%), Social care (0.2%).", "weight": 0.17},
    {"foundation": "equality", "basis": "SLOT 5: Redistribution mean 4.68 (below midpoint); SLOT 3: Inequality (1.1%), Welfare (0.4%), Housing (2.3%).", "weight": 0.11},
    {"foundation": "sanctity", "basis": "SLOT 3: Morals (0.3%) and Gender/sexuality/family (0.1%) low; some purity cues via Environment (6.1%).", "weight": 0.05}
  ]
}
